class Node:
    __slots__ = (
        "char",
        "index",
        "next_array",
        "has_cul",
        "is_same",
        "next_count",
        "next_list",
        "count_array",
    )

    def __init__(self, char, index, n):
        self.char = char
        self.index = index
        self.next_array = [None] * 26
        self.has_cul = False
        self.is_same = False
        self.next_count = 0
        self.next_list = []
        self.count_array = [0] * n

    def add_next(self, index, node):
        if self.next_array[index] is None:
            self.next_count += 1
            self.next_array[index] = node
            self.next_list.append(node)


def find(node):
    if node.has_cul:
        return

    node.count_array[0] += 1
    for next_node in node.next_list:
        find(next_node)
        for i, count in enumerate(next_node.count_array):
            if count > 0:
                node.count_array[i + 1] += count

    node.has_cul = True


