    n = int(data[0])
    k = int(data[1])
    string = data[2].decode()

    letters = [False] * 26
    nodes = []

    for i, char in enumerate(string):
        node = Node(char, i, n)
        char_index = ord(char) - ord("a")
        if letters[char_index]:
            node.is_same = True
        else:
            letters[char_index] = True
        nodes.append(node)

    for i in range(len(nodes)):
        current = nodes[i]
        for j in range(i + 1, len(nodes)):
            next_node = nodes[j]
            current.add_next(ord(next_node.char) - ord("a"), next_node)

    for node in nodes:
        find(node)

    total_count_array = [0] * n
    for i in range(n):
        for node in nodes:
            if not node.is_same:
                total_count_array[i] += node.count_array[i]

    total_cost = 0
    select_count = 0

    for i in range(n - 1, -1, -1):
        if select_count + total_count_array[i] < k:
            total_cost += (n - 1 - i) * total_count_array[i]
            select_count += total_count_array[i]
        else:
            over = select_count + total_count_array[i] - k
            selected = total_count_array[i] - over
            total_cost += (n - 1 - i) * selected
            select_count += selected
            break

    if select_count < k:
        if select_count == k - 1:
            print(total_cost + n)
        else:
            print(-1)
    else:
        print(total_cost)


